def _logo_pil():
    """Ícono de la pestaña del navegador: el logo de Olist, decodificado desde el base64
    embebido más arriba (así no depende de un archivo externo)."""
    try:
        import io
        from PIL import Image
        return Image.open(io.BytesIO(base64.b64decode(LOGO_B64)))
    except Exception:
        return "🛍️"


