def estilizar(fig, showlegend=None, height=None, extra_margin=None):
    """Aplica el tema claro de olist.com (fondo blanco, texto navy, grilla sutil)
    a cualquier gráfico de Plotly."""
    layout_kwargs = dict(
        font_family="Plus Jakarta Sans", font_color=TEXTO_GRAFICO,
        paper_bgcolor=BG_PAGE, plot_bgcolor=BG_PAGE,
        margin=dict(t=55, b=35, l=10, r=10),
        legend=dict(bgcolor="rgba(0,0,0,0)"),
    )
    if showlegend is not None:
        layout_kwargs["showlegend"] = showlegend
    if height is not None:
        layout_kwargs["height"] = height
    if extra_margin:
        layout_kwargs["margin"].update(extra_margin)
    fig.update_layout(**layout_kwargs)
    fig.update_xaxes(gridcolor=GRID_COLOR, zerolinecolor=GRID_COLOR, linecolor=GRID_COLOR)
    fig.update_yaxes(gridcolor=GRID_COLOR, zerolinecolor=GRID_COLOR, linecolor=GRID_COLOR)
    return fig


def kpi_card(col, valor, etiqueta):
    """Indicador general, con el st.metric nativo (sin HTML embebido)."""
    col.metric(etiqueta, valor)


def insight_box(texto):
    """Lectura de un gráfico: párrafo con etiqueta editorial, sin recuadro ni ícono."""
    st.markdown(f"**Lectura:** {texto}")


def oportunidad_box(texto):
    """Sugerencia de negocio: mismo tratamiento, con otra etiqueta."""
    st.markdown(f"**En la práctica:** {texto}")


def chart_card(fig, titulo, height=None):
    """Gráfico de Plotly en un contenedor con borde, con el título como encabezado
    nativo arriba (sin pastillas ni HTML embebido)."""
    fig.update_layout(title=None)
    margin_actual = fig.layout.margin
    fig.update_layout(margin=dict(
        t=14,
        b=margin_actual.b if margin_actual and margin_actual.b is not None else 35,
        l=margin_actual.l if margin_actual and margin_actual.l is not None else 10,
        r=margin_actual.r if margin_actual and margin_actual.r is not None else 10,
    ))
    if height is not None:
        fig.update_layout(height=height)
    with st.container(border=True):
        st.markdown(f"#### {titulo}")
        st.plotly_chart(fig, width="stretch")


def imagen_card(b64_data, titulo, caption=None):
    """Igual que chart_card, pero para una imagen embebida (por ejemplo, una nube de
    palabras) renderizada con st.image en vez de un gráfico interactivo."""
    with st.container(border=True):
        st.markdown(f"#### {titulo}")
        st.image(io.BytesIO(base64.b64decode(b64_data)), width="stretch")
        if caption:
            st.caption(caption)


