def _foto_sobre_blanco(b64_data):
    """Las fotos embebidas vinieron con los bordes difuminados hacia el fondo oscuro del
    diseño anterior. Acá los difumino hacia el blanco del tema nuevo (con un suavizado
    de ~15% del borde) para que no quede un halo oscuro sobre la página clara."""
    try:
        from PIL import Image

        imagen = Image.open(io.BytesIO(base64.b64decode(b64_data))).convert("RGBA")
        ancho, alto = imagen.size
        borde = 0.15
        xs = np.linspace(0, 1, ancho)
        ys = np.linspace(0, 1, alto)
        suave_x = np.clip(np.minimum(xs, 1 - xs) / borde, 0, 1)
        suave_y = np.clip(np.minimum(ys, 1 - ys) / borde, 0, 1)
        suave_x = suave_x * suave_x * (3 - 2 * suave_x)  # smoothstep
        suave_y = suave_y * suave_y * (3 - 2 * suave_y)
        alfa = (np.outer(suave_y, suave_x) * 255).astype("uint8")
        base = Image.new("RGBA", imagen.size, (255, 255, 255, 255))
        base.paste(imagen, (0, 0), Image.fromarray(alfa))
        salida = io.BytesIO()
        base.convert("RGB").save(salida, format="PNG")
        salida.seek(0)
        return salida
    except Exception:
        return io.BytesIO(base64.b64decode(b64_data))


